/* eslint-env serviceworker */
/* global clients */

// Offline support.
//
// The app is used on phones, on mobile data, often on the move — and until
// now losing signal meant losing the app entirely, including notes the
// student had already read on that device. This keeps the shell and anything
// already fetched available without a connection.
//
// Hand-rolled rather than generated by a build plugin. Vite already
// content-hashes every asset, which is the hard part of cache invalidation;
// what's left is small enough that a readable file beats a new dependency and
// an extra build step in the deploy.

// BUMP THIS ON ANY DEPLOY THAT CHANGES THE SHELL OR THE CACHING RULES.
//
// The activate handler deletes every cache whose name is not in ALL_CACHES,
// which is the right mechanism and did nothing for a year because the version
// in the name never changed. The cost is quiet: SHELL_CACHE holds `/` — the
// built index.html, naming that build's hashed bundles — and it is written
// once at install and never revalidated. A device that installed the worker
// months ago keeps serving that index.html on every offline cold start, so
// offline is pinned to a build whose assets may no longer exist on the server.
const VERSION = 'v2';
const SHELL_CACHE = `shell-${VERSION}`;
const ASSET_CACHE = `assets-${VERSION}`;
const API_CACHE = `api-${VERSION}`;
const ALL_CACHES = [SHELL_CACHE, ASSET_CACHE, API_CACHE];

// Everything needed to render *something* on a cold offline start. Hashed
// bundles are deliberately absent — their names change every build, and the
// asset handler below picks them up on first visit anyway.
const SHELL_URLS = [
  '/',
  '/manifest.json',
  // Both logo artworks: which one the header asks for depends on the theme,
  // and someone who switches to dark while offline should still get a mark
  // they can see rather than a broken image.
  '/logo-nav.png',
  '/logo-nav-dark.png',
  '/favicon-192.png',
  '/favicon-512.png',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      // addAll is all-or-nothing: one 404 would abandon the whole install and
      // leave the student with no offline support at all, silently.
      .then((cache) => Promise.allSettled(SHELL_URLS.map((u) => cache.add(u))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => !ALL_CACHES.includes(k)).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

// Logging out has to drop the cached API responses with it. Without this, the
// next person to open the app on a shared or handed-down phone could be served
// the previous student's progress and highlights straight out of the cache.
self.addEventListener('message', (event) => {
  if (event.data?.type === 'CLEAR_API_CACHE') {
    event.waitUntil(caches.delete(API_CACHE));
  }
});

const isAsset = (url) => url.pathname.startsWith('/assets/') || /\.(png|ico|svg|woff2?)$/.test(url.pathname);

// Content-hashed and immutable, so once it's cached it never needs revalidating.
async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request);
  if (hit) return hit;
  const res = await fetch(request);
  if (res.ok) cache.put(request, res.clone());
  return res;
}

// Fresh when there's signal, last-known-good when there isn't.
async function networkFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  try {
    const res = await fetch(request);
    // Only 200s are worth keeping. Caching a 401 would pin a logged-out
    // response in place and make the app look broken after signing back in.
    if (res.ok) cache.put(request, res.clone());
    return res;
  } catch (err) {
    const hit = await cache.match(request);
    if (hit) {
      // Marked so the client can tell "this is from your last visit" apart
      // from a live response and say so in the UI.
      const headers = new Headers(hit.headers);
      headers.set('X-From-Cache', '1');
      return new Response(hit.body, { status: hit.status, statusText: hit.statusText, headers });
    }
    throw err;
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return; // never cache a write
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return; // leave third parties alone

  // Client-side routing means every deep link is really the same shell. Serve
  // it from cache when offline so /subsections/1713 still opens.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request).catch(() => caches.match('/', { cacheName: SHELL_CACHE }).then((r) => r || caches.match('/')))
    );
    return;
  }

  if (url.pathname.startsWith('/api/')) {
    event.respondWith(networkFirst(request, API_CACHE));
    return;
  }

  if (isAsset(url)) {
    event.respondWith(cacheFirst(request, ASSET_CACHE));
  }
});
